1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::fs;
4	use std::path::Path;
5	use std::process::ExitCode;
6	
7	const VERSION: &str = "0.1.0";
8	
9	const USAGE: &str = "\
10	Usage:
11	    roottrace root <file>
12	    roottrace prove <file> <record-index>
13	    roottrace --version
14	
15	Commands:
16	    root <file>
17	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
18	        as one line of 64 lowercase hexadecimal characters.
19	
20	    prove <file> <record-index>
21	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
22	        record at <record-index> within the whole batch. The index is
23	        0-based and counts records in file order: 0 is the first record,
24	        1 the second, and so on; the same content at multiple positions gets
25	        the proof for the exact position given, with no deduplication. Output
26	        is one JSON object with the fields tree_size, leaf_index, root and
27	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
28	        exactly one record).
29	
30	        Example:
31	            roottrace prove batch.txt 0
32	
33	Exit status:
34	    0  success
35	    1  the file cannot be read, or the record index does not exist
36	    2  usage error (unknown command, missing or extra arguments, bad index)";
37	
38	fn main() -> ExitCode {
39	    // Raw OS arguments: file paths are handed to the filesystem exactly as
40	    // received, byte for byte. On Unix a path may contain bytes that are not
41	    // valid UTF-8 (e.g. 0xff); such a path is not invalid and must reach the
42	    // file rather than aborting argument collection. Only the command name
43	    // and the record index are required to be UTF-8 text.
44	    let args: Vec<OsString> = env::args_os().skip(1).collect();
45	    match args.as_slice() {
46	        [flag] if flag == OsStr::new("--version") => {
47	            println!("roottrace {VERSION}");
48	            ExitCode::SUCCESS
49	        }
50	        [cmd, path] if cmd == OsStr::new("root") => match merkle_root_of_file(Path::new(path)) {
51	            Ok(root) => {
52	                println!("{}", hex(&root));
53	                ExitCode::SUCCESS
54	            }
55	            Err(reason) => {
56	                eprintln!("roottrace: {reason}");
57	                ExitCode::FAILURE
58	            }
59	        },
60	        [cmd, path, index] if cmd == OsStr::new("prove") => match parse_index(index) {
61	            Some(index) => match proof_for_file(Path::new(path), index) {
62	                Ok(proof) => {
63	                    println!("{}", proof);
64	                    ExitCode::SUCCESS
65	                }
66	                Err(ProveError::Read(reason)) => {
67	                    eprintln!("roottrace: {reason}");
68	                    ExitCode::FAILURE
69	                }
70	                Err(ProveError::Missing(index, size)) => {
71	                    if size == 0 {
72	                        eprintln!(
73	                            "roottrace: record index {index} does not exist: the file holds zero records"
74	                        );
75	                    } else {
76	                        eprintln!(
77	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
78	                            size - 1
79	                        );
80	                    }
81	                    ExitCode::FAILURE
82	                }
83	            },
84	            None => {
85	                let shown = index.to_string_lossy();
86	                eprintln!("roottrace: invalid record index '{shown}': expected a decimal non-negative integer of ASCII digits");
87	                eprintln!("{USAGE}");
88	                ExitCode::from(2)
89	            }
90	        },
91	        _ => {
92	            eprintln!("{USAGE}");
93	            ExitCode::from(2)
94	        }
95	    }
96	}
97	
98	enum ProveError {
99	    Read(String),
100	    Missing(u64, u64),
101	}
102	
103	/// Render a path for a human-readable error message. This is used ONLY in
104	/// diagnostics: the filesystem is always given the raw `Path`, never this
105	/// lossy rendering, so a file whose name contains 0xff is not confused with a
106	/// differently named file that merely displays the same way.
107	fn display_path(path: &Path) -> String {
108	    path.to_string_lossy().into_owned()
109	}
110	
111	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
112	    let data = fs::read(path).map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
113	    Ok(mth(&split_records(&data)))
114	}
115	
116	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
117	    let data = fs::read(path)
118	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
119	    let records = split_records(&data);
120	    let size = records.len() as u64;
121	    if index >= size {
122	        return Err(ProveError::Missing(index, size));
123	    }
124	    let idx = index as usize;
125	    let (root, audit_path) = root_and_path(&records, idx);
126	    Ok(proof_json(size, index, &root, &audit_path))
127	}
128	
129	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
130	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
131	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
132	/// UTF-8) is rejected as a usage error.
133	fn parse_index(arg: &OsStr) -> Option<u64> {
134	    let text = arg.to_str()?;
135	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
136	        return None;
137	    }
138	    let mut value: u64 = 0;
139	    for b in text.bytes() {
140	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
141	    }
142	    Some(value)
143	}
