145	/// Build the one-line JSON object printed by `prove`: integer tree_size and
146	/// leaf_index, the lowercase-hex root, and the audit path as a JSON array of
147	/// lowercase-hex hashes ordered leaf to root.
148	fn proof_json(tree_size: u64, leaf_index: u64, root: &[u8; 32], audit_path: &[[u8; 32]]) -> String {
149	    let mut out = String::new();
150	    out.push_str("{\"tree_size\":");
151	    out.push_str(&tree_size.to_string());
152	    out.push_str(",\"leaf_index\":");
153	    out.push_str(&leaf_index.to_string());
154	    out.push_str(",\"root\":\"");
155	    out.push_str(&hex(root));
156	    out.push_str("\",\"audit_path\":[");
157	    for (i, node) in audit_path.iter().enumerate() {
158	        if i > 0 {
159	            out.push(',');
160	        }
161	        out.push('"');
162	        out.push_str(&hex(node));
163	        out.push('"');
164	    }
165	    out.push_str("]}");
166	    out
167	}
