169	/// Split raw bytes into records on LF (0x0a). The separator is not part of
170	/// any record. A trailing LF terminates the last record without adding an
171	/// empty one; an empty file yields zero records.
172	fn split_records(data: &[u8]) -> Vec<&[u8]> {
173	    if data.is_empty() {
174	        return Vec::new();
175	    }
176	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
177	    if data.last() == Some(&b'\n') {
178	        records.pop();
179	    }
180	    records
181	}
