183	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data).
184	fn leaf_hash(data: &[u8]) -> [u8; 32] {
185	    let mut input = Vec::with_capacity(1 + data.len());
186	    input.push(0x00);
187	    input.extend_from_slice(data);
188	    sha256(&input)
189	}
190	
191	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
192	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
193	    let mut input = Vec::with_capacity(65);
194	    input.push(0x01);
195	    input.extend_from_slice(left);
196	    input.extend_from_slice(right);
197	    sha256(&input)
198	}
199	
200	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256.
201	fn mth(leaves: &[&[u8]]) -> [u8; 32] {
202	    match leaves.len() {
203	        0 => sha256(&[]),
204	        1 => leaf_hash(leaves[0]),
205	        n => {
206	            // Largest power of two strictly smaller than n.
207	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
208	            node_hash(&mth(&leaves[..k]), &mth(&leaves[k..]))
209	        }
210	    }
211	}
212	
213	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
214	/// with the Merkle Audit Path for the record at `m`, computed in a single
215	/// traversal. Every leaf hash and every subtree hash is computed exactly
216	/// once: each interior hash on the path from the leaf to the root feeds both
217	/// the root computation and (for the sibling subtree) the audit path, so
218	/// producing a proof never rehashes a record byte or a subtree that already
219	/// contributed to the root.
220	///
221	/// ```text
222	/// PATH(m, [d0]) = []
223	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
224	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
225	/// ```
226	///
227	/// with k the largest power of two strictly smaller than n. Uneven batches
228	/// are handled by the recursion itself: no leaf is duplicated and no empty
229	/// record is appended to round the size up to a power of two. The returned
230	/// path is ordered from the leaf level up to the root.
231	fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
232	    let n = leaves.len();
233	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
234	    let mut path = Vec::new();
235	    let root = root_and_path_rec(leaves, m, &mut path);
236	    (root, path)
237	}
238	
239	fn root_and_path_rec(leaves: &[&[u8]], m: usize, path: &mut Vec<[u8; 32]>) -> [u8; 32] {
240	    let n = leaves.len();
241	    if n == 1 {
242	        return leaf_hash(leaves[0]);
243	    }
244	    // Largest power of two strictly smaller than n.
245	    let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
246	    if m < k {
247	        let left = root_and_path_rec(&leaves[..k], m, path);
248	        let right = mth(&leaves[k..]);
249	        path.push(right);
250	        node_hash(&left, &right)
251	    } else {
252	        let left = mth(&leaves[..k]);
253	        let right = root_and_path_rec(&leaves[k..], m - k, path);
254	        path.push(left);
255	        node_hash(&left, &right)
256	    }
257	}
