259	fn hex(digest: &[u8; 32]) -> String {
260	    let mut s = String::with_capacity(64);
261	    for b in digest {
262	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
263	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
264	    }
265	    s
266	}
