289	fn sha256(data: &[u8]) -> [u8; 32] {
290	    #[cfg(test)]
291	    SHA256_CALLS.with(|c| c.set(c.get() + 1));
292	    let mut h: [u32; 8] = [
293	        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
294	        0x5be0cd19,
295	    ];
296	
297	    let bit_len = (data.len() as u64).wrapping_mul(8);
298	    let mut msg = data.to_vec();
299	    msg.push(0x80);
300	    while msg.len() % 64 != 56 {
301	        msg.push(0);
302	    }
303	    msg.extend_from_slice(&bit_len.to_be_bytes());
304	
305	    for block in msg.chunks_exact(64) {
306	        let mut w = [0u32; 64];
307	        for (i, word) in block.chunks_exact(4).enumerate() {
308	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
309	        }
310	        for i in 16..64 {
311	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
312	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
313	            w[i] = w[i - 16]
314	                .wrapping_add(s0)
315	                .wrapping_add(w[i - 7])
316	                .wrapping_add(s1);
317	        }
318	
319	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
320	        for i in 0..64 {
321	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
322	            let ch = (e & f) ^ ((!e) & g);
323	            let t1 = hh
324	                .wrapping_add(s1)
325	                .wrapping_add(ch)
326	                .wrapping_add(K[i])
327	                .wrapping_add(w[i]);
328	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
329	            let maj = (a & b) ^ (a & c) ^ (b & c);
330	            let t2 = s0.wrapping_add(maj);
331	            hh = g;
332	            g = f;
333	            f = e;
334	            e = d.wrapping_add(t1);
335	            d = c;
336	            c = b;
337	            b = a;
338	            a = t1.wrapping_add(t2);
339	        }
340	
341	        h[0] = h[0].wrapping_add(a);
342	        h[1] = h[1].wrapping_add(b);
343	        h[2] = h[2].wrapping_add(c);
344	        h[3] = h[3].wrapping_add(d);
345	        h[4] = h[4].wrapping_add(e);
346	        h[5] = h[5].wrapping_add(f);
347	        h[6] = h[6].wrapping_add(g);
348	        h[7] = h[7].wrapping_add(hh);
349	    }
350	
351	    let mut out = [0u8; 32];
352	    for (i, word) in h.iter().enumerate() {
353	        out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
354	    }
355	    out
356	}
