359	mod tests {
360	    use super::*;
361	    use std::os::unix::ffi::OsStrExt;
362	
363	    fn hex_of(d: &[u8; 32]) -> String {
364	        hex(d)
365	    }
366	
367	    /// Verify an RFC 6962 inclusion proof with the RFC's recursive verifier:
368	    /// it re-derives the combination order from the tree geometry (k =
369	    /// largest power of two below the current subtree size) while consuming
370	    /// exactly the supplied sibling hashes. A wrong length, order or hash
371	    /// fails; the root computed here must equal the tree root.
372	    fn verify_proof(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
373	        assert!(m < n);
374	        fn sub(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]], pos: &mut usize) -> [u8; 32] {
375	            if n == 1 {
376	                return leaf_hash(leaf);
377	            }
378	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
379	            if m < k {
380	                let left = sub(leaf, m, k, path, pos);
381	                assert!(*pos < path.len(), "proof too short");
382	                let right = path[*pos];
383	                *pos += 1;
384	                node_hash(&left, &right)
385	            } else {
386	                let right = sub(leaf, m - k, n - k, path, pos);
387	                assert!(*pos < path.len(), "proof too short");
388	                let left = path[*pos];
389	                *pos += 1;
390	                node_hash(&left, &right)
391	            }
392	        }
393	        let mut pos = 0;
394	        let root = sub(leaf, m, n, path, &mut pos);
395	        assert_eq!(pos, path.len(), "proof too long: {pos} consumed of {}", path.len());
396	        root
397	    }
