399	    #[test]
400	    fn sha256_known_vectors() {
401	        assert_eq!(
402	            hex_of(&sha256(b"")),
403	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
404	        );
405	        assert_eq!(
406	            hex_of(&sha256(b"abc")),
407	            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
408	        );
409	        // Longer than one block.
410	        assert_eq!(
411	            hex_of(&sha256(
412	                b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"
413	            )),
414	            "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"
415	        );
416	    }
