418	    #[test]
419	    fn record_splitting() {
420	        assert_eq!(split_records(b""), Vec::<&[u8]>::new());
421	        assert_eq!(split_records(b"\n"), vec![b"".as_slice()]);
422	        assert_eq!(split_records(b"a\nb"), vec![b"a".as_slice(), b"b".as_slice()]);
423	        assert_eq!(split_records(b"a\nb\n"), vec![b"a".as_slice(), b"b".as_slice()]);
424	        assert_eq!(split_records(b"a\n\n"), vec![b"a".as_slice(), b"".as_slice()]);
425	        assert_eq!(split_records(b"a\n\n\n"), vec![b"a".as_slice(), b"".as_slice(), b"".as_slice()]);
426	        // CR is content, not a separator.
427	        assert_eq!(split_records(b"a\r\nb\r\n"), vec![b"a\r".as_slice(), b"b\r".as_slice()]);
428	        // Non-UTF-8 bytes are fine.
429	        assert_eq!(split_records(b"\xff\xfe\n\x00"), vec![b"\xff\xfe".as_slice(), b"\x00".as_slice()]);
430	    }
