432	    #[test]
433	    fn mth_rfc6962() {
434	        // Empty tree: SHA-256 of empty input.
435	        assert_eq!(hex_of(&mth(&[])), hex_of(&sha256(b"")));
436	        // Single leaf: SHA-256(0x00 || leaf).
437	        let leaf = b"hello";
438	        let mut expect = vec![0x00];
439	        expect.extend_from_slice(leaf);
440	        assert_eq!(hex_of(&mth(&[leaf])), hex_of(&sha256(&expect)));
441	        // Two leaves: SHA-256(0x01 || L || R).
442	        let l = mth(&[b"a"]);
443	        let r = mth(&[b"b"]);
444	        let mut expect = vec![0x01];
445	        expect.extend_from_slice(&l);
446	        expect.extend_from_slice(&r);
447	        assert_eq!(hex_of(&mth(&[b"a", b"b"])), hex_of(&sha256(&expect)));
448	        // Three leaves: split k=2, right subtree is a single leaf.
449	        let left = mth(&[b"a", b"b"]);
450	        let right = mth(&[b"c"]);
451	        let mut expect = vec![0x01];
452	        expect.extend_from_slice(&left);
453	        expect.extend_from_slice(&right);
454	        assert_eq!(hex_of(&mth(&[b"a", b"b", b"c"])), hex_of(&sha256(&expect)));
455	    }
