457	    #[test]
458	    fn audit_paths_verify_at_every_position_for_many_sizes() {
459	        // Sizes both sides of several power-of-two boundaries (uneven sizes
460	        // must not pad with empty or duplicated trailing records).
461	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 129, 257]).collect();
462	        for n in sizes {
463	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
464	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
465	            let root = mth(&refs);
466	            for m in 0..n {
467	                let (fused_root, path) = root_and_path(&refs, m);
468	                assert_eq!(
469	                    hex_of(&fused_root),
470	                    hex_of(&root),
471	                    "single-pass root must equal mth at n={n}, m={m}"
472	                );
473	                if n == 1 {
474	                    assert!(path.is_empty(), "single record must have an empty path");
475	                } else {
476	                    // Path length is bounded by the tree depth; for an even
477	                    // power-of-two batch every position sits at full depth.
478	                    let depth = usize::BITS - (n - 1).leading_zeros();
479	                    if n.is_power_of_two() {
480	                        assert_eq!(path.len(), depth as usize, "n={n}, m={m}");
481	                    } else {
482	                        assert!(path.len() <= depth as usize, "n={n}, m={m}");
483	                    }
484	                }
485	                let computed = verify_proof(refs[m], m, n, &path);
486	                assert_eq!(hex_of(&computed), hex_of(&root), "proof mismatch at n={n}, m={m}");
487	            }
488	        }
489	    }
