        assert!(proof_bytes("{\"tree_size\":\"abc}").is_err());
        assert!(proof_bytes("{\"tree_size\":\"a\\xb\"}").is_err());
        assert!(proof_bytes("{\"tree_size\":\"a\nb\"}").is_err());
    }
